using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.InputSystem;using RestaurantPreview;
namespace IdleRestaurant{
 public sealed class RestaurantCleanupView:MonoBehaviour{
  sealed class MessView{public Transform root,model,ring;public int count;}
  RestaurantGame game;RestaurantWorld world;RestaurantApp app;Material hintMaterial;readonly Dictionary<int,MessView> nodes=new Dictionary<int,MessView>();Person worker;Transform broom,cloth;int workerVisit=-1,lastBrush=-1;
  public int VisibleMesses=>nodes.Count;public Person Worker=>worker;
  public void Setup(RestaurantGame g,RestaurantWorld w,RestaurantApp a){game=g;world=w;app=a;hintMaterial=new Material(g.Catalog.nightLampMaterial?g.Catalog.nightLampMaterial:Models.Mat("#DFBC6E")){name="Cleanup tap halo"};hintMaterial.EnableKeyword("_EMISSION");hintMaterial.SetColor("_BaseColor",Models.C("#DFBC6E"));hintMaterial.SetColor("_EmissionColor",new Color(.28f,.16f,.035f));Refresh();}
  void Update(){if(game==null)return;Refresh();UpdateWorker();if(app&&app.CanTapCleanup){var touch=Touchscreen.current?.primaryTouch;if(touch!=null&&touch.press.wasPressedThisFrame)TryTap(touch.position.ReadValue());else if(Mouse.current!=null&&Mouse.current.leftButton.wasPressedThisFrame)TryTap(Mouse.current.position.ReadValue());}}
  public bool TryTap(Vector2 position){if(!app||!app.CanTapCleanup||!world.viewCamera||!world.viewCamera.enabled)return false;var evt=new PointerEventData(EventSystem.current){position=position};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(evt,hits);if(hits.Any(h=>h.gameObject.GetComponentInParent<UnityEngine.UI.Button>()))return false;if(!world.viewCamera.pixelRect.Contains(position))return false;float best=Mathf.Max(24,Screen.width*.055f);bool found=false;foreach(var node in nodes.Values){var screen=world.viewCamera.WorldToScreenPoint(node.root.position);if(screen.z<=0)continue;float distance=Vector2.Distance(position,screen);if(distance<best){best=distance;found=true;}}if(!found)return false;bool accepted=game.RequestCleanup(world.shown);if(accepted)app.Save();return accepted;}
  void Refresh(){var list=game.State.outlets[world.shown].dirt;foreach(int id in nodes.Keys.Where(id=>!list.Any(m=>m.id==id)).ToArray()){nodes[id].root.gameObject.SetActive(false);Destroy(nodes[id].root.gameObject);nodes.Remove(id);}foreach(var m in list){if(!nodes.TryGetValue(m.id,out var v)){v=Create(m);nodes[m.id]=v;}if(v.count!=m.count){v.model.gameObject.SetActive(false);Destroy(v.model.gameObject);v.model=BuildModel(v.root,m);v.count=m.count;}float y=MessHeight(m);v.root.localPosition=new Vector3(m.x,y,m.z);if(m.kind==0&&game.State.seconds-m.created<.45&&m.sourceSeat>=0){var seat=world.room.GetComponentsInChildren<RestaurantSeat>().FirstOrDefault(q=>q.index==m.sourceSeat);if(seat)v.root.localPosition=Vector3.Lerp(seat.plate,v.root.localPosition,Mathf.SmoothStep(0,1,(float)((game.State.seconds-m.created)/.45)));}v.root.gameObject.SetActive(game.State.introComplete);float pulse=game.State.reducedMotion?1:1+.055f*Mathf.Sin(Time.unscaledTime*3+m.id);v.ring.localScale=Vector3.one*pulse;var job=game.State.cleanupJob;float amount=job.active&&job.outlet==world.shown&&job.target==m.id&&job.phase==1?Mathf.Clamp01((float)(job.clock/game.Balance.cleanupSeconds)):0;v.model.localScale=Vector3.one*(1-.8f*amount);}}
  float MessHeight(CleanupMess m){if(m.kind!=0)return -.005f;var s=game.State.outlets[world.shown];return s.upgrades[6]+s.upgrades[7]+s.upgrades[8]>=game.Journey.visualUpgradeMilestones[0]?.8515f:.8275f;}
  MessView Create(CleanupMess m){var root=Models.Group("Cleanup mess "+m.id,transform,new Vector3(m.x,MessHeight(m),m.z));var model=BuildModel(root,m);var points=new List<Vector3>();for(int i=0;i<=24;i++){float a=i*Mathf.PI*2/24;points.Add(new Vector3(Mathf.Cos(a)*.29f,.01f,Mathf.Sin(a)*.29f));}var ring=Models.Tube(root,points,.014f,"#DFBC6E",6);ring.name="Tap halo";ring.GetComponent<MeshRenderer>().sharedMaterial=hintMaterial;var click=root.gameObject.AddComponent<SphereCollider>();click.radius=.31f;click.isTrigger=true;return new MessView{root=root,model=model,ring=ring,count=m.count};}
  Transform BuildModel(Transform parent,CleanupMess m){var r=Models.Group("Editable dirt model",parent,Vector3.zero);if(m.kind==0){for(int i=0;i<Mathf.Clamp(m.count,1,3);i++){Models.Cylinder(r,new Vector3(0,i*.035f,0),.20f,.025f,"#E7E0CC");Models.Cylinder(r,new Vector3(0,.018f+i*.035f,0),.15f,.012f,"#B89B73");}for(int i=0;i<4;i++)Models.Ball(r,new Vector3(Mathf.Sin(i*2)*.1f,.035f+m.count*.035f,Mathf.Cos(i*2)*.1f),new Vector3(.055f,.018f,.04f),i%2==0?"#90704D":"#B7824D");}else if(m.kind==1){for(int i=0;i<3;i++){var paper=Models.Box(r,new Vector3((i-1)*.065f,.015f+i*.006f,0),new Vector3(.17f,.025f,.16f),i%2==0?"#F1E9D3":"#D7CEB7",.025f);paper.localRotation=Quaternion.Euler(i*9,i*33,i*12);}Models.Ball(r,new Vector3(.04f,.04f,0),new Vector3(.07f,.015f,.05f),"#A6A383");}else{var cup=Models.Group("Fallen paper cup",r,new Vector3(0,.095f,0));cup.localRotation=Quaternion.Euler(0,25,82);Models.Cylinder(cup,Vector3.zero,.10f,.23f,"#EEE6D1");Models.Cylinder(cup,new Vector3(0,.09f,0),.111f,.025f,"#D6A879");Models.Cylinder(cup,new Vector3(0,.105f,0),.085f,.012f,"#81715C");Models.Cylinder(cup,new Vector3(0,-.04f,0),.102f,.055f,"#7E9A8C");}RestaurantWorld.CombineStatic(r);r.gameObject.AddComponent<RestaurantActorMarker>();return r;}
  void UpdateWorker(){var job=game.State.cleanupJob;bool visible=job.active&&job.outlet==world.shown;if(!visible){if(worker!=null)worker.root.gameObject.SetActive(false);return;}if(workerVisit!=job.id||worker==null){if(worker!=null)Destroy(worker.root.gameObject);var variants=game.Catalog.janitorVariants;worker=variants!=null&&variants.Length>0?new Person(transform,new Vector3(job.x,0,job.z),variants[(job.id-1)%variants.Length]):RestaurantCharacterArt.Create(transform,new Vector3(job.x,0,job.z),(job.id-1)%2*3,3);workerVisit=job.id;broom=Models.Group("Janitor broom",worker.root,new Vector3(.30f,0,-.35f));Models.Cylinder(broom,new Vector3(0,.49f,0),.022f,.90f,"#A98B5D");Models.Box(broom,new Vector3(0,.075f,0),new Vector3(.38f,.10f,.15f),"#D2B772",.025f);Models.Box(broom,new Vector3(0,.13f,0),new Vector3(.40f,.05f,.16f),"#67978C",.02f);cloth=Models.Box(worker.rightArm,new Vector3(0,-.37f,-.02f),new Vector3(.18f,.035f,.13f),"#F0EBD7",.015f);lastBrush=-1;}
   worker.root.gameObject.SetActive(true);var target=game.State.outlets[job.outlet].dirt.FirstOrDefault(m=>m.id==job.target);bool table=job.phase==1&&target!=null&&target.kind==0;HumanMotion motion=job.phase==1?(table?HumanMotion.CleaningTable:HumanMotion.CleaningFloor):HumanMotion.Walking;RestaurantAnimation.Pose(worker,motion,Time.time,new Vector3(job.x,0,job.z),job.yaw,job.id,(float)(job.clock/game.Balance.cleanupSeconds),game.State.reducedMotion);broom.gameObject.SetActive(!table);cloth.gameObject.SetActive(table);if(job.phase!=1)worker.rightArm.localRotation=Quaternion.Euler(95,0,-4);broom.localRotation=Quaternion.Euler(0,0,job.phase==1&&!game.State.reducedMotion?Mathf.Sin(Time.time*6)*7:0);if(job.phase==1&&lastBrush!=job.target){lastBrush=job.target;if(app)app.PlayCleanupBrush();}}
  void OnDestroy(){if(hintMaterial)Destroy(hintMaterial);}
 }
}
